# Parse the context to find June instances
lines = context.strip().split('\n')
june_instances = []

for line in lines:
    if '||' in line and 'Jun' in line:
        june_instances.append(line)

print("June instances found:")
for inst in june_instances:
    print(inst)
print(f"\nTotal June instances: {len(june_instances)}")
